<script setup lang="ts">
import {onMounted} from 'vue';
import {t,formatAmount} from '@kuaixie/i18n';
import {useSavedCommerce,type SavedKind} from '@kuaixie/ui/useSavedCommerce';
import {uniEventValue} from '../utils/uniEvent';
import {api} from '../api/client';
const props=defineProps<{kind:SavedKind}>();const p=useSavedCommerce(api,props.kind,async()=>Boolean((await uni.showModal({title:t('saved.remove'),content:t('saved.confirmRemove')})).confirm));
function setDefault(event:unknown){p.draft.value.isDefault=uniEventValue(event)===true}
function openProduct(id:string){uni.navigateTo({url:'/pages/product-detail/index?id='+encodeURIComponent(id)})}
onMounted(()=>{void p.load()});
</script>
<template><view class="saved-panel"><text class="op-back" @click="uni.navigateBack()">‹ {{$t('m2.mobile.back')}}</text><view class="op-title">{{$t(kind==='addresses'?'migration.address':kind==='cart'?'migration.cart':'migration.favorites')}}</view><view v-if="p.error.value" class="op-error">{{p.error.value}}</view><button :disabled="p.busy.value" @click="p.load(false)">{{$t('common.retry')}}</button>
 <template v-if="kind==='addresses'"><view class="op-card"><text>{{$t('v15.receiver')}}</text><input v-model="p.draft.value.contactName" maxlength="64"/><text>{{$t('v15.phoneContact')}}</text><input v-model="p.draft.value.contactPhone" maxlength="32"/><text>{{$t('saved.province')}}</text><input v-model="p.draft.value.province" maxlength="64"/><text>{{$t('account.city')}}</text><input v-model="p.draft.value.city" maxlength="64"/><text>{{$t('saved.district')}}</text><input v-model="p.draft.value.district" maxlength="64"/><text>{{$t('v15.address')}}</text><textarea v-model="p.draft.value.detail" maxlength="512"/><view>{{$t('saved.default')}}<switch :checked="p.draft.value.isDefault" @change="setDefault"/></view><button :disabled="p.busy.value" @click="p.save">{{$t('account.save')}}</button><button v-if="p.editing.value" @click="p.reset">{{$t('product.cancel')}}</button></view><view v-for="row in p.addresses.value" :key="row.id" class="op-card"><view>{{row.contact_name}} · {{row.contact_phone}}</view><text>{{row.province}} {{row.city}} {{row.district}} {{row.detail}}</text><text v-if="row.is_default">{{$t('saved.default')}}</text><button :disabled="p.busy.value" @click="p.edit(row)">{{$t('product.edit')}}</button><button :disabled="p.busy.value" @click="p.remove(row.id)">{{$t('saved.remove')}}</button></view></template>
 <template v-else-if="kind==='cart'"><view>{{$t('saved.cartNotice')}}</view><view v-for="row in p.cart.value" :key="row.id" class="op-card"><view @click="openProduct(row.product_id)">{{row.name||$t('saved.unavailable')}} · {{formatAmount(row.price,'CNY')}} ›</view><text>{{$t(row.available?'product.on':'saved.unavailable')}}</text><input :value="row.qty" type="number" :disabled="p.busy.value||!row.available" @confirm="p.quantity(row,String(uniEventValue($event)??''))" @blur="p.quantity(row,String(uniEventValue($event)??''))"/><button :disabled="p.busy.value" @click="p.remove(row.product_id)">{{$t('saved.remove')}}</button></view></template>
 <template v-else><view v-for="row in p.favorites.value" :key="row.id" class="op-card"><view @click="row.title&&row.target_type==='product'&&openProduct(row.target_id)">{{row.title||$t('saved.unavailable')}} ›</view><button :disabled="p.busy.value" @click="p.remove(row.target_id,row.target_type)">{{$t('saved.remove')}}</button></view></template><button v-if="p.more.value" :disabled="p.busy.value" @click="p.load(true)">{{$t('account.more')}}</button></view></template>
<style scoped>.saved-panel{padding:28rpx;min-height:100vh;background:var(--kx-background,#f8fafc)}.saved-panel input,.saved-panel textarea{padding:15rpx;border:1rpx solid #cbd5e1;border-radius:10rpx;margin:12rpx 0;width:100%;box-sizing:border-box}.saved-panel button{font-size:25rpx;color:white;background:var(--kx-accent,#0e7490);margin-top:12rpx}.saved-panel text{display:block;font-size:25rpx;line-height:1.6}</style>
